static int b64u_decode(const char *in, unsigned char *out, int outmax) {
    int val = 0, valb = -8, n = 0;
    for (const char *p = in; *p; p++) {
        unsigned char c = (unsigned char)*p;
        if (c == '=' || c == '\n' || c == '\r') continue;
        if (c >= 'A' && c <= 'Z') c = c - 'A';
        else if (c >= 'a' && c <= 'z') c = c - 'a' + 26;
        else if (c >= '0' && c <= '9') c = c - '0' + 52;
        else if (c == '-') c = 62;
        else if (c == '_') c = 63;
        else return -1;
        val = (val << 6) + c;
        valb += 6;
        if (valb >= 0) {
            if (n >= outmax) return -1;
            out[n++] = (unsigned char)((val >> valb) & 0xFF);
            valb -= 8;
        }
