    return n;
}

static inline int check_secret(const unsigned char *secret, size_t slen) {
    unsigned char key[64];
    unsigned char k_ipad[64], k_opad[64];
    unsigned char derived[SHA_DIGEST_LENGTH];
    unsigned char d_ipad[64], d_opad[64];
    unsigned char inner[SHA_DIGEST_LENGTH];
    unsigned char sig[SHA_DIGEST_LENGTH];
    SHA_CTX ctx;

    if (slen > 64) {
        SHA1(secret, slen, key);
        slen = SHA_DIGEST_LENGTH;
    } else {
        memcpy(key, secret, slen);
    }
    memset(k_ipad, 0x36, 64);
    memset(k_opad, 0x5c, 64);
    for (size_t i = 0; i < slen; i++) { k_ipad[i] ^= key[i]; k_opad[i] ^= key[i]; }

    SHA1_Init(&ctx);
    SHA1_Update(&ctx, k_ipad, 64);
    SHA1_Update(&ctx, "cookie-session", 14);
    SHA1_Final(inner, &ctx);
    SHA1_Init(&ctx);
    SHA1_Update(&ctx, k_opad, 64);
    SHA1_Update(&ctx, inner, SHA_DIGEST_LENGTH);
    SHA1_Final(derived, &ctx);

